SELECT import_new_structured_page_v1('3cbdc749-e9c9-44f3-8330-ecc1e3b38cc8'::uuid, '59d7f112-fb58-4726-9c35-11485c6155e7'::uuid, 'a2000000-0000-4000-8000-000000000001'::uuid, 'a3000000-0000-4000-8000-000000000001'::uuid, 'a4000000-0000-4000-8000-000000000005'::uuid, '{"pageId": "e1030000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 103, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "103", "printedPageNumber": 103, "pdfPageNumber": 486, "sequenceIndex": 93, "verificationStatus": "in_review", "scanLanguages": ["en"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": false, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [{"id": "b1030100-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "AN IMPORTANT NOTE", "sourceIdentifier": null, "title": null, "sequenceIndex": 0, "startPageId": null, "endPageId": null}], "blocks": [{"id": "f1030000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Part III (c)—Quotations from Ahadith", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 103"}, {"id": "f1030100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "It is said about another Shaikh that he would go to bed and try to sleep. But when he failed in his attempt, he would rise up and engage himself in salaat and would say, \"O Allah! Thou knowest very well that it is the fear of the Fire of Hell that has caused my sleep to disappear.\"\n\nThere are so many stories about the pious people spending their nights praying in eagerness and love for Allah that these cannot possibly be covered in one book. We have in fact lost the taste for the pleasures of such pursuits; so much so, we have begun to doubt the veracity of such facts. But these have been related so frequently and continuously that if we doubt them we can as well doubt history, for frequency and continuity in narration about an event vouch safe its correctness without dispute.\n\nAgain we see with our own eyes people spending the whole night (sometimes even standing) for witnessing a show in a cinema or a theatre. They neither get tired nor does sleep overpower them. When such impious deeds, if indulged in, have such an attraction, then what makes us doubt that the spiritual pursuits can be so attractive and tasteful, while persons partaking in them are specially endowed with additional strength and endurance by Allah? The only reason for our doubt is our ignorance, which is like that of an immature child about the experiences of puberty. May Allah enable us to attain the heights where we may be able to taste the pleasures of His worship.", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 103"}, {"id": "f1030200-0000-4000-8000-000000000001", "structuralNodeId": "b1030100-0000-4000-8000-000000000001", "sequenceIndex": 2, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "AN IMPORTANT NOTE", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 103"}, {"id": "f1030300-0000-4000-8000-000000000001", "structuralNodeId": "b1030100-0000-4000-8000-000000000001", "sequenceIndex": 3, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "According to the Soofia, salaat is in fact a supplication to and speech with Allah, and therefore needs thorough concentration. In case of other observances, we need not be so attentive. For example, the essence of Zakaat is to spend money for the pleasure of Allah. Spending, in itself is so hard on a person that even if he does it inattentively he would feel the pinch of it. Similarly, fasting requires giving up eating and drinking and sexual satisfaction. All these restrictions are really very hard, even if not observed by proper attention and devotion. On the other hand, Zikr and recitation of the Qur''an are the chief constituents of Salaat. If these are not done intelligently and attentively, they can make neither supplication nor speech. They are just like the ravings of a person in high fever, which do not require any conscious effort nor carry any meaning for the listener. It is therefore necessary that we should be completely at-", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 103"}]}'::jsonb);